#define TFT_MOSI 7
#define TFT_SCLK 15
#define TFT_CS   4
#define TFT_DC   6
#define TFT_RST  5

void sendByte(uint8_t b) {
  for (int i = 7; i >= 0; i--) {
    digitalWrite(TFT_MOSI, (b >> i) & 1);
    digitalWrite(TFT_SCLK, HIGH);
    digitalWrite(TFT_SCLK, LOW);
  }
}

void cmd(uint8_t c) {
  digitalWrite(TFT_DC, LOW);
  digitalWrite(TFT_CS, LOW);
  sendByte(c);
  digitalWrite(TFT_CS, HIGH);
}

void dat(uint8_t d) {
  digitalWrite(TFT_DC, HIGH);
  digitalWrite(TFT_CS, LOW);
  sendByte(d);
  digitalWrite(TFT_CS, HIGH);
}

void initDisplay() {
  pinMode(TFT_MOSI, OUTPUT);
  pinMode(TFT_SCLK, OUTPUT);
  pinMode(TFT_CS, OUTPUT);
  pinMode(TFT_DC, OUTPUT);
  pinMode(TFT_RST, OUTPUT);
  digitalWrite(TFT_SCLK, LOW);
  digitalWrite(TFT_CS, HIGH);

  digitalWrite(TFT_RST, HIGH); delay(20);
  digitalWrite(TFT_RST, LOW);  delay(100);
  digitalWrite(TFT_RST, HIGH); delay(200);

  cmd(0x01); delay(150);
  cmd(0x28);
  cmd(0xCF); dat(0x00); dat(0xC1); dat(0x30);
  cmd(0xED); dat(0x64); dat(0x03); dat(0x12); dat(0x81);
  cmd(0xE8); dat(0x85); dat(0x00); dat(0x78);
  cmd(0xCB); dat(0x39); dat(0x2C); dat(0x00); dat(0x34); dat(0x02);
  cmd(0xF7); dat(0x20);
  cmd(0xEA); dat(0x00); dat(0x00);
  cmd(0xC0); dat(0x23);
  cmd(0xC1); dat(0x10);
  cmd(0xC5); dat(0x3E); dat(0x28);
  cmd(0xC7); dat(0x86);
  cmd(0x36); dat(0xE8);          // хэвтээ 320x240 (цонхтой таарна)
  cmd(0x3A); dat(0x55);          // 16 bit өнгө
  cmd(0xB1); dat(0x00); dat(0x18);
  cmd(0xB6); dat(0x08); dat(0x82); dat(0x27);
  cmd(0xF2); dat(0x00);
  cmd(0x26); dat(0x01);
  cmd(0xE0);
  const uint8_t pg[] = {0x0F,0x31,0x2B,0x0C,0x0E,0x08,0x4E,0xF1,0x37,0x07,0x10,0x03,0x0E,0x09,0x00};
  for (int i = 0; i < 15; i++) dat(pg[i]);
  cmd(0xE1);
  const uint8_t ng[] = {0x00,0x0E,0x14,0x03,0x11,0x07,0x31,0xC1,0x48,0x08,0x0F,0x0C,0x31,0x36,0x0F};
  for (int i = 0; i < 15; i++) dat(ng[i]);
  cmd(0x20);                     // inversion OFF
  cmd(0x13);                     // normal mode
  cmd(0x11); delay(150);
  cmd(0x29); delay(50);
}

void fillScreen(uint16_t color) {
  cmd(0x2A); dat(0x00); dat(0x00); dat(0x01); dat(0x3F);   // x 0..319
  cmd(0x2B); dat(0x00); dat(0x00); dat(0x00); dat(0xEF);   // y 0..239
  cmd(0x2C);
  digitalWrite(TFT_DC, HIGH);
  digitalWrite(TFT_CS, LOW);
  uint8_t hi = color >> 8, lo = color & 0xFF;
  for (long i = 0; i < 320L * 240L; i++) {
    sendByte(hi);
    sendByte(lo);
  }
  digitalWrite(TFT_CS, HIGH);
}

void setup() {
  Serial.begin(115200);
  delay(1500);
  Serial.println("start");
  initDisplay();
  Serial.println("init ok");
  fillScreen(0x001F);            // цэнхэр
  Serial.println("blue done");
}

void loop() {
  Serial.println("running");
  delay(1000);
}
